export const challenges = rawChallenges.map((challenge) => ({
  brief: challenge.description,
  deepDive: 'Investigue o cenário, use apenas os dados fictícios do laboratório e relacione a descoberta com uma defesa aplicável em sistemas reais.',
  defense: 'Validação, privilégio mínimo, registros úteis e resposta proporcional ao risco.',
  reference: { label: 'OWASP — Recursos de segurança', url: 'https://owasp.org/' },
  ...trackDefaults[challenge.track],
  ...challenge,
}));

export const getChallenge = (id) => challenges.find((challenge) => challenge.id === id);
export const isUnlocked = (challenge, completed = {}) => !challenge.requires || challenge.requires.every((id) => completed[id]);
